code='''def transform(grid):
 out=[r[:] for r in grid]
 # isolated 8 initiates a rectangular extension to the adjacent vertical 1 segment
 h,w=len(grid),len(grid[0])
 for r in range(h):
  for c in range(w):
   if grid[r][c]!=8: continue
   out[r][c]=4
   # extend right across the rows of the neighboring vertical line
   if c+1<w and grid[r][c+1]!=1:
    cols=[j for j in range(c+1,w) if grid[r][j]==1]
    if cols:
     edge=min(cols)
     rr=[i for i in range(h) if grid[i][edge]==1]
     for i in rr:
      if i>=r:
       for j in range(c+1,edge): out[i][j]=8
 return out
'''
open(p,'w').write(code); exec(code); out=transform(grid); print(*out[5:11],sep='\n')

